import { useTranslation } from 'react-i18next';
import { View } from 'react-native';

import { AppCard, AppHeader, AppScreen, AppText } from '@/components/ui';
import { makeStyles } from '@/theme';

import licenses from '../licenses.json';

/** Direct runtime dependencies and their licenses (generated by `npm run licenses`). */
export function LicensesView() {
  const styles = useStyles();
  const { t } = useTranslation('settings');

  return (
    <AppScreen
      header={<AppHeader title={t('licenses.title')} back />}
      edges={['top', 'left', 'right', 'bottom']}>
      <AppText variant="bodySmall" color="textSecondary">
        {t('licenses.intro')}
      </AppText>
      <AppCard padding="lg" style={styles.card}>
        {licenses.map((entry, i) => (
          <View key={entry.name}>
            {i > 0 ? <View style={styles.divider} /> : null}
            <View style={styles.row} accessible>
              <AppText variant="bodyMedium" script="latin" style={styles.name}>
                {entry.name}
              </AppText>
              <AppText variant="caption" color="textSecondary" script="latin">
                {`${entry.version} · ${entry.license ?? t('licenses.unknown')}`}
              </AppText>
            </View>
          </View>
        ))}
      </AppCard>
    </AppScreen>
  );
}

const useStyles = makeStyles((t) => ({
  card: { paddingVertical: t.spacing.xs },
  row: { paddingVertical: t.spacing.md, gap: t.spacing.xs },
  name: { flexShrink: 1 },
  divider: { height: t.layout.hairline, backgroundColor: t.colors.border },
}));
